import Foundation

struct Entry {
    let hour: Int
    let temp: Int
}

func filterEntries(list: [Entry], minTemp: Int) -> [Int] {
    var result: [Int] = []
    for item in list {
        if item.temp >= minTemp {
            result.append(item.hour)
        }
    }
    return result
}

let items = [Entry(hour: 9, temp: 65), Entry(hour: 10, temp: 72), Entry(hour: 11, temp: 75)]
let warmHours = filterEntries(list: items, minTemp: 70)
print("Warm count: \(warmHours.count)")

