import Foundation

enum ReloadDecision {
    case atEnd
    case never
}

func policyForInterval(hours: Int) -> ReloadDecision {
    if hours > 0 {
        return .atEnd
    }
    return .never
}

let choice = policyForInterval(hours: 4)
if choice == .atEnd {
    print("Policy: atEnd")
} else {
    print("Policy: never")
}

import Foundation

struct BudgetTracker {
    var usedReloads: Int
    let maxDailyBudget: Int

    func remainingBudget() -> Int {
        let diff = maxDailyBudget - usedReloads
        if diff > 0 {
            return diff
        }
        return 0
    }
}

let tracker = BudgetTracker(usedReloads: 35, maxDailyBudget: 50)
print("Remaining: \(tracker.remainingBudget())")

