import Foundation

class EntryQueue {
    var timestamps: [Int] = []

    func addEntry(time: Int) {
        timestamps.append(time)
    }

    func activeEntry(currentTime: Int) -> Int {
        var lastValid = 0
        for t in timestamps {
            if t <= currentTime {
                lastValid = t
            }
        }
        return lastValid
    }
}

let queue = EntryQueue()
queue.addEntry(time: 100)
queue.addEntry(time: 200)
queue.addEntry(time: 300)
print("Active: \(queue.activeEntry(currentTime: 250))")

