import Foundation

class SharedStorageStore {
    let suiteName: String
    var storage: [String: String] = [:]

    init(suiteName: String) {
        self.suiteName = suiteName
    }

    func setString(value: String, key: String) {
        storage[key] = value
    }

    func getString(key: String) -> String? {
        return storage[key]
    }
}

let store = SharedStorageStore(suiteName: "group.com.example.app")
store.setString(value: "sunny", key: "weather")
print("Stored: \(store.getString(key: "weather") ?? "none")")
